"/* ==========================================================================
   Triton Course Registration System - Modern, Accessible & Colorful CSS
   WCAG 2.2 AA Compliant: High Contrast, Visible Focus Rings, Semantic Layout
   ========================================================================== */

/* --- CSS Variables & Design Tokens --- */
:root {
  /* Vibrant & Accessible Primary Palette (Contrast >= 4.5:1 against light bg) */
  --primary: #1e3a8a;          /* Deep Royal Navy (Accessible contrast on white > 10:1) */
  --primary-hover: #172554;    /* Dark Navy */
  --primary-light: #eff6ff;    /* Very light ice blue */
  --primary-border: #93c5fd;

  --secondary: #0d9488;        /* Deep Vibrant Teal (Accessible contrast > 4.6:1) */
  --secondary-hover: #115e59;
  --secondary-light: #f0fdfa;

  --accent-purple: #6d28d9;    /* Rich Purple (Contrast > 7.1:1 on white) */
  --accent-purple-light: #f5f3ff;
  --accent-purple-border: #c4b5fd;

  --accent-amber: #b45309;     /* Deep Amber / Bronze (Contrast > 4.7:1 on white) */
  --accent-amber-light: #fffbeb;

  --accent-rose: #be123c;      /* Deep Crimson / Rose */
  --accent-rose-light: #fff1f2;

  --success: #15803d;          /* Forest Green */
  --success-light: #f0fdf4;
  --success-border: #86efac;

  --danger: #b91c1c;           /* Vivid Crimson (Contrast > 5.5:1) */
  --danger-light: #fef2f2;
  --danger-border: #fca5a5;

  --warning-bg: #fffbeb;
  --warning-text: #92400e;
  --warning-border: #fcd34d;

  --info-bg: #e0f2fe;
  --info-text: #0369a1;
  --info-border: #7dd3fc;

  /* Neutrals */
  --bg-main: #f8fafc;
  --bg-surface: #ffffff;
  --text-main: #0f172a;        /* High contrast near-black (15:1) */
  --text-muted: #475569;       /* Slate grey (Contrast > 5.2:1) */
  --border-light: #cbd5e1;     /* Contrast >= 3:1 for form control boundaries */
  --border-focus: #1d4ed8;     /* 3px focus ring */

  /* Typography */
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto
